// =====================================================================
// DIAGNOSE – Mollie. Rein lesend, keine Schreibzugriffe.
// Ziel: Zustand der Klarna-Zahlungen zu Altbestellungen feststellen.
// =====================================================================
const CONFIG = {
  // Wie viele Bestellungen ansehen? Klein anfangen.
  anzahlBestellungen: 10,

  // Nur Bestellungen, deren Lieferschein in diesem Zeitraum versendet wurde.
  tageZurueck: 30,

  // Mollie
  mollieBasisUrl: 'https://api.mollie.com/v2',

  // Nur diese Zahlungsarten ansehen. Leeres Array = alle.
  // Der erste Lauf sollte leer bleiben, damit wir sehen, was es ueberhaupt gibt.
  nurZahlungsarten: []
};

return [{ json: { config: CONFIG } }];

// Endpunkt nach Praefix waehlen.
//   tr_  -> Payments API   /payments/{id}
//   ord_ -> Orders  API    /orders/{id}
// Beide werden rein LESEND abgefragt.
const config = $('Config').first().json.config;
const item   = $input.item.json;
const id     = String(item.MollieId ?? '').trim();

let variante = 'unbekannt';
let url      = null;

if (id.startsWith('tr_'))       { variante = 'payment'; url = config.mollieBasisUrl + '/payments/' + id; }
else if (id.startsWith('ord_')) { variante = 'order';   url = config.mollieBasisUrl + '/orders/'   + id; }

return { json: { ...item, mollieId: id, mollieVariante: variante, mollieUrl: url,
                 abfragbar: url !== null } };

// Antwort auswerten – Mollie Orders API UND Payments API.
// Node-Modus: "Run Once for Each Item".
//
// WICHTIG: Mollie antwortet mit Content-Type application/hal+json. n8n parst das
// nicht automatisch, sondern legt den kompletten Body als STRING in $json.data ab.
// Deshalb hier erst parsen, sonst sind alle Felder still null.
const src = $('URL bauen').item.json;
const roh = $input.item.json;

// --- Antwort in ein Objekt bringen, egal in welcher Form sie ankommt ----
let resp = roh;
let parseFehler = null;

if (typeof roh?.data === 'string') {
  try { resp = JSON.parse(roh.data); }
  catch (e) { parseFehler = 'data war String, aber kein JSON: ' + e.message; }
} else if (typeof roh === 'string') {
  try { resp = JSON.parse(roh); }
  catch (e) { parseFehler = 'Antwort war String, aber kein JSON: ' + e.message; }
} else if (roh?.data && typeof roh.data === 'object') {
  resp = roh.data;
}

const geld = v => (v && v.value !== undefined)
  ? (v.value + ' ' + (v.currency ?? '')) : null;
const zahl = v => (v === null || v === undefined) ? null : Number(v);

// --- Fehlerantwort erkennen -------------------------------------------
// Mollie liefert bei Fehlern status als ZAHL plus title/detail.
const istFehler = parseFehler !== null
               || typeof resp?.status === 'number'
               || resp?.detail !== undefined;

const httpFehler = parseFehler
  ? parseFehler
  : (istFehler ? [resp?.status, resp?.title, resp?.detail].filter(Boolean).join(' – ') : null);

// --- Orderlines auswerten (nur Orders API) ----------------------------
const lines = Array.isArray(resp?.lines) ? resp.lines : [];
const echteLines = lines.filter(l => l?.type !== 'shipping_fee');

const summe = (arr, f) => arr.reduce((s, x) => s + (Number(f(x)) || 0), 0);

const versendbarOffen = summe(lines, l => l.shippableQuantity);
const mengeGesamt     = summe(echteLines, l => l.quantity);
const mengeVersendet  = summe(echteLines, l => l.quantityShipped);

// --- Bewertung --------------------------------------------------------
// Orders API:   created / paid / authorized / shipping / completed / canceled / expired
// Payments API: open / authorized / paid / canceled / expired / failed
const status = istFehler ? null : (resp?.status ?? null);

let bewertung;
if (istFehler)                          bewertung = 'FEHLER – siehe httpFehler';
else if (status === 'completed')        bewertung = 'abgeschlossen – nichts zu tun';
else if (status === 'paid')             bewertung = 'bereits bezahlt – nichts zu tun';
else if (status === 'expired')          bewertung = 'VERFALLEN – nicht mehr einziehbar';
else if (status === 'canceled')         bewertung = 'storniert';
else if (status === 'failed')           bewertung = 'fehlgeschlagen';
else if (status === 'authorized')       bewertung = lines.length === 0
                                          ? 'OFFEN – Capture moeglich'          // Payments API, keine lines
                                          : (versendbarOffen > 0
                                              ? 'OFFEN – Shipment moeglich'
                                              : 'authorized, aber nichts mehr versendbar');
else if (status === 'shipping')         bewertung = versendbarOffen > 0
                                          ? 'teilweise versendet – Rest offen'
                                          : 'teilweise versendet, nichts mehr versendbar';
else if (status === 'created')          bewertung = 'nie autorisiert – kein Zahlungsversprechen';
else if (status === 'open')             bewertung = 'offen, noch nicht autorisiert';
else                                    bewertung = 'unklar: ' + (status ?? 'kein status');

return { json: {
  // --- Herkunft ---
  cBestellNr:       src.cBestellNr,
  kBestellung:      src.kBestellung,
  mollieId:         src.mollieId,
  variante:         src.mollieVariante,
  zahlungsartJTL:   src.Zahlungsart ?? null,
  betragJTL:        src.BetragJTL ?? null,
  letzterVersand:   src.LetzterVersand ?? null,

  // --- Zustand bei Mollie ---
  httpFehler,
  status,
  method:           istFehler ? null : (resp?.method ?? null),
  mode:             istFehler ? null : (resp?.mode ?? null),
  betragMollie:     geld(resp?.amount),
  bereitsErfasst:   geld(resp?.amountCaptured),
  authorizedAt:     resp?.authorizedAt ?? null,
  paidAt:           resp?.paidAt ?? null,
  completedAt:      resp?.completedAt ?? null,
  expiredAt:        resp?.expiredAt ?? null,
  captureMode:      resp?.captureMode ?? null,   // nur Payments API
  captureBefore:    resp?.captureBefore ?? null, // nur Payments API

  // --- Positionen (nur Orders API) ---
  anzahlLines:      lines.length || null,
  mengeGesamt:      lines.length ? mengeGesamt    : null,
  mengeVersendet:   lines.length ? mengeVersendet : null,
  versendbarOffen:  lines.length ? versendbarOffen : null,
  lineStatus:       lines.length
                      ? [...new Set(lines.map(l => l.status))].join(', ')
                      : null,

  bewertung,
  rohantwort: resp
} };

// Praefix weder tr_ noch ord_ – nicht abfragbar.
const s = $input.item.json;
return { json: {
  cBestellNr: s.cBestellNr, kBestellung: s.kBestellung, mollieId: s.mollieId,
  variante: s.mollieVariante, zahlungsartJTL: s.Zahlungsart ?? null,
  betragJTL: s.BetragJTL ?? null, letzterVersand: s.LetzterVersand ?? null,
  bewertung: 'nicht abfragbar – unbekanntes Praefix' } };

// Verdichtung: was ist der Gesamtbefund?
const zeilen = $input.all().map(i => i.json).filter(z => z && z.mollieId);

const zaehl = (feld) => {
  const m = {};
  for (const z of zeilen) { const k = z[feld] ?? '(leer)'; m[k] = (m[k] || 0) + 1; }
  return m;
};

// Nur diese Zustaende sind fuer Path B ueberhaupt adressierbar.
const offen = zeilen.filter(z =>
  z.bewertung === 'OFFEN – Capture moeglich' ||
  z.bewertung === 'OFFEN – Shipment moeglich' ||
  z.bewertung === 'teilweise versendet – Rest offen');

const summeOffen = offen.reduce((s, z) => s + (Number(z.betragJTL) || 0), 0);

return [{ json: {
  geprueft:          zeilen.length,

  // --- der eigentliche Befund ---
  adressierbar:      offen.length,
  summeAdressierbar: Math.round(summeOffen * 100) / 100,
  proBewertung:      zaehl('bewertung'),

  proStatus:         zaehl('status'),
  proVariante:       zaehl('variante'),
  proMethod:         zaehl('method'),
  proZahlungsartJTL: zaehl('zahlungsartJTL'),

  offeneFaelle: offen.map(z => ({
    bestellnummer: z.cBestellNr, mollieId: z.mollieId, status: z.status,
    betrag: z.betragMollie ?? z.betragJTL, versendbarOffen: z.versendbarOffen,
    captureBefore: z.captureBefore ?? null })).slice(0, 25),

  fehler: zeilen.filter(z => z.httpFehler)
                .map(z => ({ bestellnummer: z.cBestellNr, mollieId: z.mollieId,
                             fehler: z.httpFehler })).slice(0, 25),

  tabelle: zeilen.map(z => { const { rohantwort, ...rest } = z; return rest; })
}}];
